const TodayFeature={id:"today",name:"Home",icon:"home",init(){},render:()=>'<div id="hsc-today-root" class="notebook-page"></div>',activate(){HomeScreenController.renderDynamicHomeScreen("hsc-today-root")},deactivate(){HomeScreenController.stopDynamicHomeScreen()},async getWeekEarnings(){const e=Utils.getStartOfWeek(),t=Utils.getEndOfWeek();return(await DB.getWeekStats(e.toISOString(),t.toISOString())).earnings},async getWeekSales(){const e=Utils.getStartOfWeek(),t=Utils.getEndOfWeek();return(await DB.getWeekStats(e.toISOString(),t.toISOString())).sales},async openEODModal(){const e=Utils.getToday();let t=[];try{t=await DB.getAppointmentsForDate(e.toISOString())}catch(e){}const o=t.filter(e=>e.outcome).length,n=t.reduce((e,t)=>"ordered"!==t.outcome?e:"number"==typeof t.commission&&t.commission>0?e+t.commission:e+TaxCalculator.estimateCommission(t.value||0),0),a=`\n      <div class="sheet-handle"></div>\n      <div class="sheet-header">\n        <h3>End of Day</h3>\n        <button class="btn btn-ghost btn-sm" onclick="App.closeModal()">\n          <span class="material-symbols-rounded">close</span>\n        </button>\n      </div>\n      <div class="sheet-body">\n        <div style="display: grid; grid-template-columns: repeat(2, 1fr); gap: 12px; margin-bottom: 20px;">\n          <div class="stat-card">\n            <div class="value">${Utils.formatCurrency(n)}</div>\n            <div class="label">Earned Today</div>\n          </div>\n          <div class="stat-card">\n            <div class="value">${o}/${t.length}</div>\n            <div class="label">Visits Done</div>\n          </div>\n        </div>\n\n        <div class="form-group">\n          <label>Anything to remember for tomorrow?</label>\n          <input type="text" class="input" id="eod-note" placeholder="e.g. Call back Mrs Jones about samples">\n        </div>\n\n        <button class="btn btn-primary btn-block" onclick="TodayFeature.completeEOD()">\n          Done for Today <span class="material-symbols-rounded">check</span>\n        </button>\n      </div>\n    `;App.openModal(a)},async completeEOD(){const e=document.getElementById("eod-note"),t=e?e.value.trim():"";if(t)try{await DB.addCommunication({type:"note",content:`EOD note: ${t}`,sentAt:(new Date).toISOString()})}catch(e){}localStorage.setItem("advisoros_last_eod",Utils.formatDate(Utils.getToday(),"iso")),App.closeModal(),Toast.show("Day complete. See you tomorrow!","success"),App.navigate("today")}};App.registerFeature(TodayFeature);
